{

		if(!stack.hasTagCompound()) {
			return;
		}

		String poolName = stack.getTagCompound().getString("pool");
		List<String> pool = GenericRecipes.blueprintPools.get(poolName);

		if(pool == null || pool.isEmpty()) {
			return;
		}
		if(poolName.startsWith(GenericRecipes.POOL_PREFIX_SECRET)) {
			list.add(TextFormatting.RED + "Cannot be copied!");
		} else {
			list.add(TextFormatting.YELLOW + "Right-click to copy (requires paper)");
		}

		for(String name : pool) {
			GenericRecipe recipe = GenericRecipes.pooledBlueprints.get(name);
			if(recipe != null) {
				list.add(recipe.getLocalizedName());
			}
		}
	}

{

    	if(!(stack.getItem() instanceof ItemCassette))
    		return;

		list.add(TextFormatting.YELLOW + I18nUtil.resolveKey("info.templatefolder", I18nUtil.resolveKey(ModItems.template_folder.getTranslationKey() + ".name")));
		list.add("");

    	list.add("Siren sound cassette:");
    	list.add("   Name: " + TrackType.getEnum(stack.getItemDamage()).getTrackTitle());
    	list.add("   Type: " + TrackType.getEnum(stack.getItemDamage()).getType().name());
    	list.add("   Volume: " + TrackType.getEnum(stack.getItemDamage()).getVolume());
	}

{
		list.add("Adds spice to the core.");
		list.add("Look at all those colors!");
	}

{

		CrucibleRecipe recipe = CrucibleRecipes.indexMapping.get(stack.getItemDamage());

		if(recipe == null) {
			return;
		}

		list.add(TextFormatting.BOLD + I18nUtil.resolveKey("info.template_out_p"));
		for(MaterialStack out : recipe.output) {
			list.add(I18nUtil.resolveKey(out.material.getUnlocalizedName()) + ": " + Mats.formatAmount(out.amount, Keyboard.isKeyDown(Keyboard.KEY_LSHIFT)));
		}

		list.add(TextFormatting.BOLD + I18nUtil.resolveKey("info.template_in_p"));

		for(MaterialStack in : recipe.input) {
			list.add(I18nUtil.resolveKey(in.material.getUnlocalizedName()) + ": " + Mats.formatAmount(in.amount, Keyboard.isKeyDown(Keyboard.KEY_LSHIFT)));
		}
	}

{
		String desc = (stack.getItem() == ModItems.laser_crystal_digamma) ? (TextFormatting.OBFUSCATED + "THERADIANCEOFATHOUSANDSUNS") : (this.getUnlocalizedNameInefficiently(stack) + ".desc");
		list.add(I18nUtil.resolveKey(desc));
		list.add(wavelength.textColor + I18nUtil.resolveKey(wavelength.name) + " - " + wavelength.textColor + I18nUtil.resolveKey(this.wavelength.wavelengthRange));
	}

{
		list.add(I18nUtil.resolveKey(getTranslationKey() + ".info"));
		list.add("   " + getType(stack, true).getLocalizedName());
		list.add(I18nUtil.resolveKey(getTranslationKey() + ".info2"));
		list.add("   " + getType(stack, false).getLocalizedName());
	}

{
		if(stack.hasTagCompound()) {
			if(getQuantity(stack) > 0) {
				list.add(getQuantity(stack) + "mB");
			} else if(getAtmospheres(stack) > 0) {
				double pressure = BobMathUtil.roundDecimal(getAtmospheres(stack), 3);
				list.add(pressure + "atm");
			}

			if(getPressure(stack) > 0) {
				list.add(TextFormatting.RED + "" + getPressure(stack) + "PU");
				list.add((BobMathUtil.getBlink() ? TextFormatting.RED : TextFormatting.DARK_RED) + "Pressurized, use compressor!");
			}
		}

		Fluids.fromID(stack.getItemDamage()).addInfo(list);
	}

{
		boolean muon = stack.hasTagCompound() && stack.getTagCompound().getBoolean("muon");
		list.add(TextFormatting.GREEN + "Depletion: " + String.format(Locale.US, "%.1f", getDurabilityForDisplay(stack) * 100D) + "%");
		list.add(TextFormatting.YELLOW + "Fuel: " + I18nUtil.resolveKey("icffuel." + getType(stack, true).name().toLowerCase(Locale.US)) + " / " + I18nUtil.resolveKey("icffuel." + getType(stack, false).name().toLowerCase(Locale.US)));
		list.add(TextFormatting.YELLOW + "Heat required: " + BobMathUtil.getShortNumber(this.getFusingDifficulty(stack)) + "TU");
		list.add(TextFormatting.YELLOW + "Reactivity multiplier: x" + (int) (getType(stack, true).reactionMult * getType(stack, false).reactionMult * 100) / 100D);
		if(muon) list.add(TextFormatting.DARK_AQUA + "Muon catalyzed!");
	}

{
		if(canOperate(stack))
			return;

		FluidType currentFluid = Fluids.fromID(stack.getTagCompound().getInteger("fluid"));

		if(currentFluid == Fluids.NONE) {
			list.add("Current environment has insufficient vapor pressure");
		} else {
			list.add("Current environment has an incompatible fluid table");
		}

		list.add("Requires: " + type.getLocalizedName() + " table");

		if(currentFluid == Fluids.NONE) {
			list.add("Releasing 0.2atm of vapor into the atmosphere will add a table on dry celestial bodies");
		} else {
			list.add("Current environment: " + currentFluid.getLocalizedName() + " table");
		}
	}

{

		long damage = getLensDamage(stack);
		int percent = (int) ((maxDamage - damage) * 100 / maxDamage);

		list.add("Durability: " + (maxDamage - damage) + "/" + maxDamage + " (" + percent + "%)");
	}

{
		Mold mold = getMold(stack);
		list.add(TextFormatting.YELLOW + mold.getTitle());

		if(mold.size == 0) list.add(TextFormatting.GOLD + I18nUtil.resolveKey(ModBlocks.foundry_mold.getTranslationKey() + ".name"));
		if(mold.size == 1) list.add(TextFormatting.RED + I18nUtil.resolveKey(ModBlocks.foundry_basin.getTranslationKey() + ".name"));
	}

{
		list.add("Use on a constructed PWR controller to generate construction diagrams");
	}

{

		String[] defaultLocs = I18nUtil.resolveKey("desc.item.pileRod").split("\\$");

		for(String loc : defaultLocs) {
			list.add(loc);
		}

		String[] descLocs = I18nUtil.resolveKey(this.getTranslationKey() + ".desc").split("\\$");

		for(String loc : descLocs) {
			list.add(loc);
		}
	}

{
		if (itemstack.getTagCompound() != null) {
			list.add("x: " + itemstack.getTagCompound().getInteger("x"));
			list.add("y: " + itemstack.getTagCompound().getInteger("y"));
			list.add("z: " + itemstack.getTagCompound().getInteger("z"));
		} else {
			list.add("No reactor selected!");
		}
	}

{

		String[] lang = I18nUtil.resolveKeyArray(ModItems.template_folder.getTranslationKey() + ".desc");
		TextFormatting color = BobMathUtil.getBlink() ? TextFormatting.RED : TextFormatting.YELLOW;
		for(String line : lang) {
			list.add(color + line);
		}
	}

src/main/java/com/hbm/items/special/Item.body:
{

		if (this == ModItems.ams_core_sing) {
			list.add("A modified undefined state of spacetime");
			list.add("used to aid in inter-gluon fusion and");
			list.add("spacetime annihilation. Yes, this destroys");
			list.add("the universe itself, slowly but steadily,");
			list.add("but at least you can power your toaster with");
			list.add("this, so it's all good.");
		}

		if (this == ModItems.ams_core_wormhole) {
			list.add("A cloud of billions of nano-wormholes which");
			list.add("deliberately fail at tunneling matter from");
			list.add("another dimension, rather it converts all");
			list.add("that matter into pure energy. That means");
			list.add("you're actively contributing to the destruction");
			list.add("of another dimension, sucking it dry like a");
			list.add("juicebox.");
			list.add("That dimension probably sucked, anyways. I");
			list.add("bet it was full of wasps or some crap, man,");
			list.add("I hate these things.");
		}

		if (this == ModItems.ams_core_eyeofharmony) {
			list.add("A star collapsing in on itself, mere nanoseconds");
			list.add("away from being turned into a black hole,");
			list.add("frozen in time. If I didn't know better I");
			list.add("would say this is some deep space magic");
			list.add("bullcrap some guy made up to sound intellectual.");
			list.add("Probably Steve from accounting. You still owe me");
			list.add("ten bucks.");
		}

		if (this == ModItems.ams_core_thingy) {
			if(MainRegistry.polaroidID == 11) {
				list.add("Yeah I'm not even gonna question that one.");
			} else {
				list.add("...");
				list.add("...");
				list.add("...am I even holding this right?");
				list.add("It's a small metal thing. I dunno where it's from");
				list.add("or what it does, maybe they found it on a");
				list.add("junkyard and sold it as some kind of antique");
				list.add("artifact. If it weren't for the fact that I can");
				list.add("actually stuff this into some great big laser");
				list.add("reactor thing, I'd probably bring it back to where");
				list.add("it belongs. In the trash.");
			}
		}
	}

{
		SolarSystem.Body body = getOreBody(stack);
		list.add("Mined on: " + I18nUtil.resolveKey("body." + body.name));

		for(CelestialBedrockOreType type : CelestialBedrockOre.get(body).types) {
			double amount = getOreAmount(stack, type);
			String typeName = I18nUtil.format("item.bedrock_ore.type." + type.suffix + ".name");
			list.add(typeName + ": " + ((int) (amount * 100)) / 100D + " (" + ItemOreDensityScanner.getColor(amount) + I18nUtil.format(ItemOreDensityScanner.translateDensity(amount)) + TextFormatting.GRAY + ")");
		}
	}

{
		if(!stack.hasTagCompound()) return;
		String key = stack.getTagCompound().getString("k");
		if(key.isEmpty()) return;

		key = "book_lore." + key + ".author";
		String loc = I18nUtil.resolveKey(key);
		if(!loc.equals(key))
			list.add(I18nUtil.resolveKey("book_lore.author", loc));
	}

{

		if(this == ModItems.cigarette) {
			list.add(TextFormatting.RED + "✓ Asbestos filter");
			list.add(TextFormatting.RED + "✓ High in tar");
			list.add(TextFormatting.RED + "✓ Tobacco contains 100% Polonium-210");
			list.add(TextFormatting.RED + "✓ Yum");
		} else {
			String[] colors = new String[] {
					TextFormatting.RED + "",
					TextFormatting.GOLD + "",
					TextFormatting.YELLOW + "",
					TextFormatting.GREEN + "",
					TextFormatting.AQUA + "",
					TextFormatting.BLUE + "",
					TextFormatting.DARK_PURPLE + "",
					TextFormatting.LIGHT_PURPLE + "",
			};
			int len = 2000;
			list.add("This can't be good for me, but I feel " + colors[(int)(System.currentTimeMillis() % len * colors.length / len)] + "GREAT");
		}
	}

{
		if (this == ModItems.cell_antimatter) {
			list.add("Warning: Exposure to matter will");
			list.add("lead to violent annihilation!");
		}
		if (this == ModItems.pellet_antimatter) {
			list.add("Very heavy antimatter cluster.");
			list.add("Gets rid of black holes.");
		}
		if (this == ModItems.cell_anti_schrabidium) {
			list.add("Warning: Exposure to matter will");
			list.add("create a fólkvangr field!");
		}
		if (this == ModItems.singularity) {
			list.add("You may be asking:");
			list.add("\"But HBM, a manifold with an undefined");
			list.add("state of spacetime? How is this possible?\"");
			list.add("Long answer short:");
			list.add("\"I have no idea!\"");
		}
		if (this == ModItems.singularity_counter_resonant) {
			list.add("Nullifies resonance of objects in");
			list.add("non-euclidean space, creates variable");
			list.add("gravity well. Spontaneously spawns");
			list.add("tesseracts. If a tesseract happens to");
			list.add("appear near you, do not look directly");
			list.add("at it.");
		}
		if (this == ModItems.singularity_super_heated) {
			list.add("Continuously heats up matter by");
			list.add("resonating every planck second.");
			list.add("Tends to catch fire or to create");
			list.add("small plasma arcs. Not edible.");
		}
		if (this == ModItems.black_hole) {
			list.add("Contains a regular singularity");
			list.add("in the center. Large enough to");
			list.add("stay stable. It's not the end");
			list.add("of the world as we know it,");
			list.add("and I don't feel fine.");
		}
		if (this == ModItems.detonator_deadman) {
			list.add("Shift right-click to set position,");
			list.add("drop to detonate!");
			if(itemstack.getTagCompound() == null)
			{
				list.add("No position set!");
			} else {
				list.add("Set pos to " + itemstack.getTagCompound().getInteger("x") + ", " + itemstack.getTagCompound().getInteger("y") + ", " + itemstack.getTagCompound().getInteger("z"));
			}
		}
		if (this == ModItems.detonator_de) {
			list.add("Explodes when dropped!");
		}
		
		list.add(TextFormatting.RED + "[" + I18nUtil.resolveKey("trait.drop") + "]");
	}

{

		long damage = getShieldDamage(stack);
		int percent = (int) ((maxDamage - damage) * 100 / maxDamage);

		list.add("Durability: " + (maxDamage - damage) + "/" + maxDamage + " (" + percent + "%)");

		list.add("Melting point: " + TextFormatting.RED + "" + maxTemp + "°C");
	}

{
		list.add("It's a gamble!");
		list.add("");
		switch(MainRegistry.polaroidID) {
		case 1: 
			list.add("Click-click-click!");
			break;
		case 2: 
			list.add("Creek!");
			break;
		case 3: 
			list.add("Bzzzt!");
			break;
		case 4: 
			list.add("TS staring off into space.");
			break;
		case 5: 
			list.add("BANG!!");
			break;
		case 6: 
			list.add("Woop!");
			break;
		case 7: 
			list.add("Poow!");
			break;
		case 8: 
			list.add("Pft!");
			break;
		case 9: 
			list.add("GF fgnevat bss vagb fcnpr.");
			break;
		case 10: 
			list.add("Backup memory #8 on 1.44 million bytes.");
			break;
		case 11: 
			list.add("PTANG!");
			break;
		case 12: 
			list.add("Bzzt-zrrt!");
			break;
		case 13: 
			list.add("Clang, click-brrthththrtrtrtrtrtr!");
			break;
		case 14: 
			list.add("KABLAM!");
			break;
		case 15: 
			list.add("PLENG!");
			break;
		case 16: 
			list.add("Wheeeeeeee-");
			break;
		case 17: 
			list.add("Thump.");
			break;
		case 18: 
			list.add("BANG! Choo-chooo! B A N G ! ! !");
			break;
		}
	}

{

		String r = TextFormatting.RED + "";
		String y = TextFormatting.YELLOW + "";
		String b = TextFormatting.BLUE + "";
		String o = TextFormatting.GOLD + "";
		String g = TextFormatting.GREEN + "";

		switch(stack.getItemDamage()) {
		case CLUMP_PEROXIDE:
			list.add(y + "[Peroxide]");
			break;
		case CLUMP_NITRIC:
